#!/usr/bin/env python3
"""Identity-stitched sessionization.

Rules:
- Every event carries cookie_id; user_id appears only on post-login events.
- If ANY event of a cookie carries a user_id, ALL of that cookie's events
  (including pre-login ones) belong to that user -- retroactive stitching.
- Sessionization keys on the resolved identity: the stitched user_id when
  the cookie ever logged in, else the raw cookie_id (anonymous).
- A new session starts when the gap since the identity's previous event
  exceeds GAP_SECONDS (30 minutes). A gap of exactly 30 minutes stays in
  the same session. Events from different cookies that resolve to the same
  user can interleave into one shared session.

Outputs:
- identity_map.json : {cookie_id: resolved_identity}
- sessions.jsonl    : one JSON object per session, sorted by start time.
"""

import json
from datetime import datetime, timedelta

GAP_SECONDS = 30 * 60

EVENTS_PATH = "events.jsonl"
IDENTITY_MAP_PATH = "identity_map.json"
SESSIONS_PATH = "sessions.jsonl"


def parse_ts(ts: str) -> datetime:
    return datetime.fromisoformat(ts.replace("Z", "+00:00"))


def load_events(path: str) -> list[dict]:
    events = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                events.append(json.loads(line))
    return events


def build_identity_map(events: list[dict]) -> dict[str, str]:
    """cookie_id -> resolved identity (user_id if the cookie ever logged in,
    else the cookie_id itself)."""
    cookie_to_user: dict[str, str] = {}
    for ev in events:
        uid = ev.get("user_id")
        if uid:
            cookie = ev["cookie_id"]
            prev = cookie_to_user.setdefault(cookie, uid)
            if prev != uid:
                raise ValueError(
                    f"cookie {cookie!r} seen with conflicting users {prev!r} and {uid!r}"
                )
    return {
        cookie: cookie_to_user.get(cookie, cookie)
        for cookie in {ev["cookie_id"] for ev in events}
    }


def sessionize(events: list[dict], identity_map: dict[str, str]) -> list[dict]:
    """Group events into per-identity sessions using the 30-minute gap rule."""
    tagged = sorted(
        (
            {
                **ev,
                "_identity": identity_map[ev["cookie_id"]],
                "_dt": parse_ts(ev["ts"]),
            }
            for ev in events
        ),
        key=lambda e: (e["_identity"], e["_dt"]),
    )

    sessions: list[dict] = []
    current = None  # {"identity", "start", "end", "events"}

    def flush(cur):
        if cur is not None:
            sessions.append(
                {
                    "identity": cur["identity"],
                    "start": cur["start"].isoformat().replace("+00:00", "Z"),
                    "end": cur["end"].isoformat().replace("+00:00", "Z"),
                    "events": cur["events"],
                    "n_events": len(cur["events"]),
                }
            )

    gap = timedelta(seconds=GAP_SECONDS)
    for ev in tagged:
        if current is None or ev["_identity"] != current["identity"] or ev["_dt"] - current["end"] > gap:
            flush(current)
            current = {"identity": ev["_identity"], "start": ev["_dt"], "end": ev["_dt"], "events": [ev]}
        else:
            current["end"] = ev["_dt"]
            current["events"].append(ev)
    flush(current)

    sessions.sort(key=lambda s: s["start"])
    for i, s in enumerate(sessions, 1):
        s["session_id"] = f"s{i:04d}"
    return sessions


def main() -> None:
    events = load_events(EVENTS_PATH)
    identity_map = build_identity_map(events)
    sessions = sessionize(events, identity_map)

    with open(IDENTITY_MAP_PATH, "w") as f:
        json.dump(identity_map, f, indent=2, sort_keys=True)
        f.write("\n")
    with open(SESSIONS_PATH, "w") as f:
        for s in sessions:
            f.write(json.dumps(s) + "\n")

    print(f"{len(identity_map)} identities resolved from {len(events)} events "
          f"into {len(sessions)} sessions")


if __name__ == "__main__":
    main()

